import { describe, expect, it } from 'vitest'
import { runChecks } from './check'
import { ExtractError, MAX_XML_BYTES, extractEInvoice, pickAttachment, type PdfJs } from './extract'
import { prettyXml } from './format'
import { EInvoiceParseError, parseEInvoice, type InvoiceView } from './parse'
import { parseXml } from './xml'

// Test files: XML generated by the backend (E01 corpus, `PDF_OUT=<dir> cargo test renders_einvoice_conformance_corpus`)
// and hand-written UBL samples. `xrechnung-mixed-rates.pdf` is the matching PDF of the corpus.
const xmlFiles = import.meta.glob<string>('./testdata/*.xml', { query: '?raw', import: 'default', eager: true })
const pdfFiles = import.meta.glob<string>('./testdata/*.pdf', { query: '?inline', import: 'default', eager: true })
const xmlOf = (name: string) => xmlFiles[`./testdata/${name}`]
const xmlNames = () => Object.keys(xmlFiles).map((p) => p.replace('./testdata/', ''))
const bytesOf = (name: string): Uint8Array => {
  const url = name.endsWith('.pdf') ? pdfFiles[`./testdata/${name}`] : `data:;base64,${btoa(unescape(encodeURIComponent(xmlOf(name))))}`
  return Uint8Array.from(atob(url.slice(url.indexOf(',') + 1)), (c) => c.charCodeAt(0))
}
const encoder = new TextEncoder()

const statuses = (view: InvoiceView) => Object.fromEntries(runChecks(view).map((r) => [r.id, r.status]))

describe('xml reader', () => {
  it('reads elements, attributes, entities, CDATA and ignores prefixes and comments', () => {
    const root = parseXml('<?xml version="1.0"?><!-- c --><a:Root xmlns:a="x" k=\'v\'><a:Child id="1">A &amp; B &#65;&#x42;</a:Child><Empty/><![CDATA[<raw>]]></a:Root>')
    expect(root.name).toBe('Root')
    expect(root.attrs).toEqual({ k: 'v' })
    expect(root.children.map((c) => c.name)).toEqual(['Child', 'Empty'])
    expect(root.children[0].text).toBe('A & B AB')
    expect(root.children[0].attrs.id).toBe('1')
    expect(root.text).toBe('<raw>')
  })

  it('does not expand custom entities (no entity expansion attacks)', () => {
    const root = parseXml('<!DOCTYPE a [<!ENTITY x "boom">]><a>&x;</a>')
    expect(root.text).toBe('&x;')
  })

  it('rejects malformed XML', () => {
    expect(() => parseXml('<a><b></a>')).toThrow()
    expect(() => parseXml('<a>')).toThrow()
    expect(() => parseXml('')).toThrow()
    expect(() => parseXml('<a/><b/>')).toThrow()
  })
})

describe('parsing the generated corpus (CII)', () => {
  it('reads an XRechnung with mixed rates', () => {
    const view = parseEInvoice(xmlOf('xrechnung-mixed-rates.xml'))
    expect(view.syntax).toBe('cii')
    expect(view.typeCode).toBe('380')
    expect(view.number).toBe('2026-001')
    expect(view.issueDate).toBe('2026-01-31')
    expect(view.currency).toBe('EUR')
    expect(view.profile).toContain('xrechnung_3.0')
    expect(view.seller.name).toBe('Muster GmbH')
    expect(view.seller.vatId).toBe('DE123456789')
    expect(view.seller.taxNumber).toBe('12/345/67890')
    expect(view.seller.contactName).toBe('Erika Muster')
    expect(view.buyer.name).toBe('Kunde AG')
    expect(view.buyerReference).toBe('04011000-12345-34')
    expect(view.items).toHaveLength(3)
    expect(view.items[0]).toMatchObject({ name: 'Beratung', quantity: 8, unit: 'HUR', price: 95, net: 760, taxCategory: 'S', taxRate: 19 })
    expect(view.taxes.map((t) => t.rate).sort((a, b) => a! - b!)).toEqual([7, 19])
    expect(view.totals.due).toBe(view.totals.grandTotal)
    expect(view.payments[0].iban).toBe('DE89370400440532013000')
  })

  it('reads a credit note with a reference to the invoice', () => {
    const view = parseEInvoice(xmlOf('credit-note-xrechnung.xml'))
    expect(view.typeCode).toBe('381')
    expect(view.precedingInvoices).toEqual([{ number: '2026-001', date: '2026-01-31' }])
  })

  it('reads a VAT exempt invoice with the reason', () => {
    const view = parseEInvoice(xmlOf('en16931-exempt.xml'))
    const exempt = view.taxes.find((t) => t.rate === 0)
    expect(exempt?.exemptionReason).toBe('Steuerfrei nach § 4 Nr. 1b UStG')
  })

  it('shows nothing unusual for every generated file', () => {
    for (const name of xmlNames().filter((n) => /^(en16931|xrechnung|credit-note).*\.xml$/.test(n))) {
      const results = runChecks(parseEInvoice(xmlOf(name)))
      const findings = results.filter((r) => r.status !== 'ok' && r.status !== 'skipped')
      expect(findings, name).toEqual([])
      expect(results.filter((r) => r.status === 'skipped'), name).toEqual([])
    }
  })
})

describe('parsing UBL', () => {
  it('reads an invoice with two rates and a line allowance', () => {
    const view = parseEInvoice(xmlOf('ubl-invoice.xml'))
    expect(view.syntax).toBe('ubl')
    expect(view.number).toBe('RE-2026-0042')
    expect(view.dueDate).toBe('2026-04-14')
    expect(view.seller.name).toBe('Lieferant Handel GmbH')
    expect(view.seller.tradeName).toBe('Lieferant Handel')
    expect(view.seller.vatId).toBe('DE123456789')
    expect(view.seller.email).toBe('erika@lieferant.example')
    expect(view.notes).toEqual(['Vielen Dank für Ihren Auftrag & Ihr Vertrauen.'])
    expect(view.items).toHaveLength(2)
    expect(view.items[0]).toMatchObject({ id: '1', quantity: 2, unit: 'HUR', price: 90, net: 165, hasAdjustments: true })
    expect(view.items[1].sellerItemId).toBe('FB-1')
    expect(view.taxes).toHaveLength(2)
    expect(view.totals).toMatchObject({ lineTotal: 212.2, taxTotal: 34.65, grandTotal: 246.85, due: 246.85 })
    expect(view.payments[0]).toMatchObject({ code: '58', iban: 'DE89370400440532013000', bic: 'COBADEFFXXX' })
    expect(view.paymentTerms).toBe('Zahlbar innerhalb von 30 Tagen netto.')
    expect(Object.values(statuses(view))).not.toContain('error')
    expect(Object.values(statuses(view))).not.toContain('warning')
  })

  it('reads a credit note', () => {
    const view = parseEInvoice(xmlOf('ubl-credit-note.xml'))
    expect(view.typeCode).toBe('381')
    expect(view.items[0]).toMatchObject({ quantity: 20, unit: 'KGM', price: 5, net: 100, taxCategory: 'K' })
    expect(view.precedingInvoices).toEqual([{ number: 'RE-2026-0042', date: '2026-03-15' }])
    expect(view.taxes[0].exemptionReason).toBe('Innergemeinschaftliche Lieferung')
    // missing optional parts do not break anything; only the missing payment details are pointed out
    expect(statuses(view)).toMatchObject({ header: 'ok', parties: 'ok', payment: 'warning', 'tax-category': 'ok' })
  })
})

describe('unsupported files', () => {
  it('names the reason', () => {
    expect(() => parseEInvoice('<html/>')).toThrow(EInvoiceParseError)
    expect(() => parseEInvoice('<CrossIndustryDocument/>')).toThrowError(/1\.x/)
    try {
      parseEInvoice('<a>')
    } catch (e) {
      expect((e as EInvoiceParseError).code).toBe('invalid_xml')
    }
  })
})

describe('plausibility check', () => {
  const base = () => parseEInvoice(xmlOf('xrechnung-mixed-rates.xml'))

  it('finds a wrong line amount', () => {
    const view = base()
    view.items[0].net = 700
    const result = runChecks(view).find((r) => r.id === 'line-math')!
    expect(result.status).toBe('error')
    expect(result.findings[0]).toContain('1')
  })

  it('finds a wrong sum of lines, tax basis, tax amount, tax total, gross total and amount due', () => {
    const view = base()
    view.totals.lineTotal! += 1
    view.taxes[0].basis! += 5
    view.taxes[1].amount! += 0.5
    view.totals.taxTotal! += 2
    view.totals.grandTotal! += 3
    view.totals.due! += 4
    expect(statuses(view)).toMatchObject({
      'line-sum': 'error',
      'tax-basis': 'error',
      'tax-amount': 'error',
      'tax-total': 'error',
      'gross-total': 'error',
      'amount-due': 'error',
    })
  })

  it('accepts a rounding difference of one cent in products only', () => {
    const view = base()
    view.taxes[0].amount! += 0.01
    view.totals.taxTotal! += 0.01
    view.totals.grandTotal! += 0.01
    view.totals.due! += 0.01
    expect(statuses(view)).toMatchObject({ 'tax-amount': 'ok', 'tax-total': 'ok', 'gross-total': 'ok', 'amount-due': 'ok' })
  })

  it('finds missing mandatory fields', () => {
    const view = base()
    view.number = undefined
    view.seller.name = undefined
    view.seller.vatId = view.seller.taxNumber = view.seller.registration = undefined
    view.buyer.country = undefined
    view.items[1].unit = undefined
    const results = Object.fromEntries(runChecks(view).map((r) => [r.id, r]))
    expect(results.header.status).toBe('error')
    expect(results.parties.findings).toHaveLength(3)
    expect(results.lines.findings[0]).toContain('2')
  })

  it('finds a missing exemption reason, wrong category rate, bad IBAN and impossible dates', () => {
    const view = parseEInvoice(xmlOf('en16931-exempt.xml'))
    view.taxes.find((t) => t.rate === 0)!.exemptionReason = undefined
    view.taxes.find((t) => t.rate === 19)!.rate = 0
    view.payments[0].iban = 'DE89370400440532013001'
    view.issueDate = '2026-02-31'
    expect(statuses(view)).toMatchObject({ 'tax-category': 'error', payment: 'warning', dates: 'warning' })
  })

  it('does not say anything about amounts that are missing but reports that it did not check them', () => {
    const view = base()
    view.totals = { lineTotal: null, allowanceTotal: null, chargeTotal: null, taxBasis: null, taxTotal: null, grandTotal: null, prepaid: null, rounding: null, due: null }
    const results = statuses(view)
    expect(results['line-sum']).toBe('skipped')
    expect(results['net-total']).toBe('skipped')
    expect(results['amount-due']).toBe('skipped')
  })

  it('finds EN 16931 rule violations, XRechnung rule violations and unknown codes', () => {
    const view = parseEInvoice(xmlOf('xrechnung-exempt.xml'))
    const findings = (id: string) => runChecks(view).find((r) => r.id === id)?.findings ?? []
    expect(statuses(view)).toMatchObject({ 'en16931-rules': 'ok', 'xrechnung-rules': 'ok', 'code-lists': 'ok' })

    view.buyerReference = undefined
    view.seller.phone = '12'
    view.seller.email = 'not-an-email'
    view.seller.vatId = 'ZZ123456789'
    view.items[0].id = undefined
    view.items[0].unit = 'kg'
    view.currency = 'XYZ'
    view.typeCode = '777'
    view.buyer.country = 'ZZ'
    view.payments[0].code = '30'
    view.payments[0].iban = undefined
    expect(statuses(view)).toMatchObject({ 'en16931-rules': 'error', 'xrechnung-rules': 'error', 'code-lists': 'error' })
    const rules = [...findings('en16931-rules'), ...findings('xrechnung-rules'), ...findings('code-lists')].join('\n')
    for (const id of ['BR-21', 'BR-61', 'BR-CO-9', 'BR-DE-15', 'BR-DE-27', 'BR-DE-28', 'BR-DE-17', 'BR-CL-01', 'BR-CL-03', 'BR-CL-14', 'BR-CL-23']) {
      expect(rules).toContain(id)
    }
  })

  it('runs the XRechnung rules only for the XRechnung profile', () => {
    const view = parseEInvoice(xmlOf('en16931-exempt.xml'))
    view.seller.phone = undefined
    expect(runChecks(view).some((r) => r.id === 'xrechnung-rules')).toBe(false)
    view.profile = 'urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0'
    expect(runChecks(view).find((r) => r.id === 'xrechnung-rules')!.findings.join('\n')).toContain('BR-DE-6')
  })

  it('every check has a title and no check is called "valid"', () => {
    for (const r of runChecks(base())) expect(`${r.title} ${r.findings.join(' ')}`).not.toMatch(/\bvalid(e|ierung)?\b|gültig\b/i)
  })
})

describe('extracting the XML', () => {
  const noPdf = async (): Promise<PdfJs> => {
    throw new Error('pdf.js must not be loaded for plain XML')
  }

  it('accepts a plain XML file without loading pdf.js', async () => {
    const result = await extractEInvoice(bytesOf('ubl-invoice.xml'), 'rechnung.xml', noPdf)
    expect(result).toMatchObject({ source: 'xml', fileName: 'rechnung.xml' })
    expect(result.xml).toContain('RE-2026-0042')
  })

  it('reads the XML from a ZUGFeRD/XRechnung PDF', async () => {
    const pdfjs = (await import('pdfjs-dist/legacy/build/pdf.mjs')) as unknown as PdfJs
    const result = await extractEInvoice(bytesOf('xrechnung-mixed-rates.pdf'), 'x.pdf', async () => pdfjs)
    expect(result).toMatchObject({ source: 'pdf', fileName: 'xrechnung.xml' })
    expect(parseEInvoice(result.xml).number).toBe('2026-001')
  })

  it('says clearly when a PDF has no XML or is not a PDF', async () => {
    const empty: PdfJs = { getDocument: () => ({ promise: Promise.resolve({ getAttachments: async () => null, getAttachmentContent: async () => null }), destroy: async () => undefined }) }
    await expect(extractEInvoice(encoder.encode('%PDF-1.7\n'), 'a.pdf', async () => empty)).rejects.toMatchObject({ code: 'no_xml' })
    await expect(extractEInvoice(encoder.encode('hello'), 'a.txt', noPdf)).rejects.toMatchObject({ code: 'unsupported' })
    await expect(extractEInvoice(new Uint8Array(), 'a.xml', noPdf)).rejects.toMatchObject({ code: 'empty' })
    await expect(extractEInvoice(encoder.encode('%PDF-1.7 garbage'), 'a.pdf', async () => ({ getDocument: () => ({ promise: Promise.reject(Object.assign(new Error('x'), { name: 'PasswordException' })), destroy: async () => undefined }) }))).rejects.toMatchObject({ code: 'pdf_encrypted' })
  })

  it('enforces the size limit', async () => {
    const big = new Uint8Array(MAX_XML_BYTES + 1).fill(0x20)
    big[0] = 0x3c
    await expect(extractEInvoice(big, 'big.xml', noPdf)).rejects.toBeInstanceOf(ExtractError)
  })

  it('prefers the known attachment names (case-insensitive) over other XML files', () => {
    const map = new Map([
      ['1', { filename: 'other.xml' }],
      ['2', { filename: 'ZUGFeRD-invoice.xml' }],
    ])
    expect(pickAttachment(map)).toEqual({ id: '2', name: 'ZUGFeRD-invoice.xml' })
    expect(pickAttachment(new Map([['1', { filename: 'note.txt' }]]))).toBeNull()
  })
})

describe('xml display', () => {
  it('indents XML that is on one line and leaves formatted XML alone', () => {
    expect(prettyXml('<a><b>x</b><c/></a>')).toBe('<a>\n  <b>x</b>\n  <c/>\n</a>')
    expect(prettyXml('<a>\n  <b/>\n  <c/>\n</a>')).toBe('<a>\n  <b/>\n  <c/>\n</a>')
  })
})
